const D = { density:.5, scale:1, energy:.45, speed:1, hue:45, x:.5, y:.5, drift:.5, twinkle:.6, style:'ambient', seed:0, act:'drift' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const frc=v=>v-Math.floor(v);
const md=(a,n)=>((a%n)+n)%n;
const lrp=(a,b,t)=>a+(b-a)*t;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};

const W=width,Hh=height,u=Math.min(W,Hh);
const H=md(P.hue,360);
const st=P.style;
const ambient=st==='ambient', sunbeam=st==='sunbeam', ash=st==='ash', schem=st==='schematic';
const NMAX=150;
const n=Math.max(6,Math.round(NMAX*clp(P.density,0,1)));
const en=P.energy*(0.5+0.6*K.intensity);

if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

// rebuild mote field on seed change
if(S.seedUsed!==P.seed){ S.seedUsed=P.seed; S.m=[]; for(let i=0;i<NMAX;i++){ S.m.push({ x:fr(i*3+1), y:fr(i*3+2), z:fr(i*3+3), ph:fr(i*3+4)*6.2832, sp:0.5+fr(i*3+5), sw:0.4+fr(i*3+6) }); } }

// dramaturgy: vertical bias by act, plus slow section sway
const act=P.act;
const vy = act==='updraft'? -0.9 : act==='settle'? 0.75 : 0.16;
const secSway = Math.sin(K.section*0.9 + K.t*0.05)*0.4;
const driftx=(P.drift-0.5)*2 + secSway*0.3;

const cx=P.x*W;

// volumetric shaft behind motes
if(sunbeam){
  blendMode(ADD); noStroke();
  const bw=u*0.55*P.scale;
  push(); translate(cx,0); rotate(0.16+0.05*Math.sin(K.t*0.18));
  for(let s2=0;s2<7;s2++){ const t=s2/7; fill(md(H+6,360),22,92, 3.4*(0.6+en)*(1-t)); rect(-bw*0.5*(0.28+t),-Hh*0.2,bw*(0.28+t),Hh*1.6); }
  pop(); blendMode(BLEND);
}

if(!schem) blendMode(ADD);
noStroke();
for(let i=0;i<n;i++){
  const m=S.m[i];
  const t=K.t*0.02*P.speed*(0.4+m.sp*0.8);
  let mx = frc(m.x + driftx*t + Math.sin(K.t*0.5*m.sw + m.ph)*0.02);
  let my = frc(m.y + vy*t*0.6 + Math.cos(K.t*0.4*m.sw + m.ph*1.3)*0.015);
  const px=mx*W, py=my*Hh;
  const tw=0.55+0.45*Math.sin(K.t*(1.2+m.sw*1.5)*P.speed+m.ph)*(0.3+P.twinkle*0.8)+A.treble*0.5;
  const sz=u*(0.004+0.016*m.z)*P.scale*(0.5+m.z*0.7);
  const a=clp(tw,0,1.4)*(0.35+en)*(ash?55:72);
  if(schem){
    stroke(md(190,360),60,100, clp(tw,0,1)*62); strokeWeight(Math.max(0.6,u*0.0012)); noFill();
    ellipse(px,py, sz*3, sz*3);
    const vv=sz*4.5; line(px,py, px+Math.cos(m.ph)*vv*(driftx*0.6+0.4), py+Math.sin(m.ph)*vv);
    noStroke();
  } else if(ash){
    fill(md(H,360), 8, lrp(60,88,m.z), a); ellipse(px,py,sz*1.7,sz*1.7);
  } else {
    const col=[md(H+(m.z-0.5)*30,360), lrp(15,45,m.z), lrp(78,100,m.z)];
    fill(col[0],col[1],col[2], a*0.55); ellipse(px,py,sz*3.4,sz*3.4);
    fill(col[0],clp(col[1]-12,0,100),100, a); ellipse(px,py,sz*1.3,sz*1.3);
  }
}
blendMode(BLEND);
drawingContext.shadowBlur=0;
